import { expect, test } from 'bun:test';
import { formatSceneColorsModule } from './format-scene-colors-module';

test('it writes the scene colours as a const module', () => {
  expect(formatSceneColorsModule({ fogShroud: '#282d38', ground: '#3d424d' }))
    .toMatchInlineSnapshot(`
      "// Generated by this package's codegen script from the scene colour tokens in @vers/panda-preset.
      // Change a colour in the preset, not here.
      export const sceneColors = {
        fogShroud: '#282d38',
        ground: '#3d424d',
      } as const;
      "
    `);
});

test('it writes the same module for the same scene colours', () => {
  expect(formatSceneColorsModule({ ground: '#3d424d' })).toStrictEqual(
    formatSceneColorsModule({ ground: '#3d424d' }),
  );
});
